import{_ as n,C as l,o as d,c as i,a2 as t,E as r,w as c,j as a,a as s}from"./chunks/framework.C2TvIV46.js";const x=JSON.parse('{"title":"Base files","description":"","frontmatter":{},"headers":[],"relativePath":"language/base-files.md","filePath":"language/base-files.md"}'),p={name:"language/base-files.md"};function g(m,e,u,h,b,v){const o=l("DocsBlock");return d(),i("div",null,[e[1]||(e[1]=t('<h1 id="base-files" tabindex="-1">Base files <a class="header-anchor" href="#base-files" aria-label="Permalink to &quot;Base files&quot;">​</a></h1><p>Some Megalo scripts inherit from a compiled parent variant using the <code>base</code> directive. This is how Bungie built <strong>variant families</strong> — one full gametype script serves as the base, and shorter derived scripts retune only metadata, teams, and options.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><p>A derived script starts with a single <code>base</code> line referencing a compiled <code>.mglo</code> file:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf.mglo&quot;</span></span></code></pre></div><p>The <code>.mglo</code> extension refers to a compiled Megalo variant, not a source <code>.txt</code> file. The editor resolves the base at compile time and merges the derived script&#39;s elements on top.</p><p>The base file is read from the compile <strong>output folder</strong> — <code>maps/megalo</code> when using MegaloEdit.exe. Compile the parent script to produce its <code>.mglo</code> before building derived variants that reference it.</p>',7)),r(o,{type:"warning",title:"Same megalo version"},{default:c(()=>[...e[0]||(e[0]=[a("p",null,[s("A derived script and its base "),a("code",null,".mglo"),s(" must target the "),a("strong",null,"same megalo encoding version"),s(". Mixing builds (for example a TU1 base with an MCC-only derived script, or bases from different "),a("a",{href:"/MegaloEvolved/beta/docs/versions/"},"Megalo versions"),s(") is not supported — compile the base and derived scripts against the same Reach build.")],-1)])]),_:1}),e[2]||(e[2]=t(`<h2 id="what-gets-inherited" tabindex="-1">What gets inherited <a class="header-anchor" href="#what-gets-inherited" aria-label="Permalink to &quot;What gets inherited&quot;">​</a></h2><p>A base file contributes its <strong>entire compiled script</strong> to the derived variant:</p><ul><li>All triggers, conditions, and actions</li><li>All variable declarations and initial values</li><li>HUD widgets, map object filters, and statistics</li><li>Loadout definitions and requisition palettes</li></ul><p>The derived script only re-specifies a <strong>restricted subset</strong> of top-level elements. Derived files can declare:</p><table tabindex="0"><thead><tr><th>Element</th><th>Purpose</th></tr></thead><tbody><tr><td><code>engine_data</code></td><td>Override gametype name, description, icon, category</td></tr><tr><td><code>teams</code></td><td>Retune team models, colors, designators</td></tr><tr><td><code>game_options</code></td><td>Override built-in options, add or lock custom options</td></tr><tr><td><code>constants</code></td><td>Add or replace constants</td></tr><tr><td><code>string_table</code> / <code>include</code></td><td>Add localized strings</td></tr><tr><td><code>loadout</code> / <code>loadout_palette</code></td><td>Override loadout definitions</td></tr><tr><td><code>map_permissions</code></td><td>Change forge placement rules</td></tr><tr><td><code>player_rating</code></td><td>Override rating parameters</td></tr></tbody></table><p>Derived files <strong>cannot</strong> add:</p><ul><li><code>variables</code></li><li><code>trigger</code></li><li><code>hud_widgets</code></li><li><code>map_object</code></li><li><code>requisition_palette</code></li><li><code>game_stats</code></li></ul><p>To change game logic, edit the base script (or create a new full script without a <code>base</code> line).</p><h2 id="retuning-options" tabindex="-1">Retuning options <a class="header-anchor" href="#retuning-options" aria-label="Permalink to &quot;Retuning options&quot;">​</a></h2><p>Derived scripts override inherited game options using the same <code>game_options</code> element:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;headhunter.mglo&quot;</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> team_headhunter_title</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">game_options</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">50</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Common patterns in derived scripts:</p><ul><li><strong><code>override</code></strong> — set a built-in engine option to a new default</li><li><strong><code>lock override</code></strong> — set a default and prevent the lobby from changing it</li><li><strong><code>option &quot;Name&quot; value</code></strong> — re-declare a custom option with a new default (shorthand form used in some derived scripts)</li></ul><h2 id="real-examples" tabindex="-1">Real examples <a class="header-anchor" href="#real-examples" aria-label="Permalink to &quot;Real examples&quot;">​</a></h2><p>Bungie shipped many variant families. Each base <code>.mglo</code> has several derived <code>.txt</code> scripts:</p><table tabindex="0"><thead><tr><th>Base</th><th>Derived variants</th></tr></thead><tbody><tr><td><code>ctf.mglo</code></td><td><code>ctf_1flag.txt</code>, <code>ctf_multiteam.txt</code>, <code>ctf_neutralflag.txt</code></td></tr><tr><td><code>headhunter.mglo</code></td><td><code>headhunter_team.txt</code>, <code>headhunter_pro.txt</code>, <code>headhunter_pro_team.txt</code></td></tr><tr><td><code>assault.mglo</code></td><td><code>assault_one_bomb.txt</code>, <code>assault_neutral_bomb.txt</code>, <code>grifball.txt</code></td></tr><tr><td><code>koth.mglo</code></td><td><code>koth_team.txt</code>, <code>koth_pro.txt</code>, <code>koth_crazyking.txt</code></td></tr><tr><td><code>infection.mglo</code></td><td><code>infection_safehavens.txt</code>, <code>infection_newhavens.txt</code></td></tr><tr><td><code>slayer.mglo</code></td><td><code>slayer_team.txt</code>, <code>slayer_pro.txt</code>, <code>slayer_classic.txt</code>, <code>SWAT.txt</code></td></tr></tbody></table><p>A typical derived script is very short:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf.mglo&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/ctf_strings.txt&quot;</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> ctf_1flag_title</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">game_options</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">lock</span><span class="megalo-text"> </span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">round_count</span><span class="megalo-text"> </span><span class="megalo-number">4</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="base-vs-include" tabindex="-1">Base vs include <a class="header-anchor" href="#base-vs-include" aria-label="Permalink to &quot;Base vs include&quot;">​</a></h2><p>These are two different composition mechanisms:</p><table tabindex="0"><thead><tr><th></th><th><code>base &quot;x.mglo&quot;</code></th><th><code>include &quot;x.txt&quot;</code></th></tr></thead><tbody><tr><td><strong>What it merges</strong></td><td>A compiled variant (binary)</td><td>Source text</td></tr><tr><td><strong>Inherits logic</strong></td><td>Yes — triggers, variables, everything</td><td>Only the included elements</td></tr><tr><td><strong>Can add triggers</strong></td><td>No</td><td>Yes</td></tr><tr><td><strong>Typical use</strong></td><td>Variant families (1-Flag CTF from CTF)</td><td>Shared strings, loadouts, common logic</td></tr></tbody></table><p>A script can use both — a derived script might <code>base</code> a compiled parent and <code>include</code> additional string tables or helper logic.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/syntax">Syntax &amp; file format</a> — includes, file structure, and <a href="/MegaloEvolved/beta/docs/language/syntax#the-element-model">element model</a></li><li><a href="/MegaloEvolved/beta/docs/language/examples">Example scripts</a> — full scripts without a base line</li></ul>`,24))])}const _=n(p,[["render",g]]);export{x as __pageData,_ as default};
